/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var name = event.payload.name.split('.');
	var obj = { ...api.state[name[0]] };
	obj[name[1]] = event.payload.id;
	return {
		propName: name[0],
		value: obj
	};
}
